<?php require_once __DIR__.'/../../includes/auth.php';requireHOD();$p=db();$departmentId=$_SESSION['user']['department_id'];$error='';if($_SERVER['REQUEST_METHOD']==='POST'){verifyCsrf();$batchId=(int)($_POST['batch_id']??0);$password=$_POST['password']??'';$confirm=trim($_POST['confirmation']??'');$q=$p->prepare("SELECT password FROM users WHERE id=? AND department_id=? AND role='hod' AND status='active'");$q->execute([$_SESSION['user']['id'],$departmentId]);$hodPassword=$q->fetchColumn();if($confirm!=='DELETE BATCH')$error='Type DELETE BATCH to confirm.';elseif(!$hodPassword||!password_verify($password,$hodPassword))$error='The HOD password is incorrect.';else{$q=$p->prepare('SELECT id FROM batches WHERE id=? AND department_id=?');$q->execute([$batchId,$departmentId]);if(!$q->fetchColumn())$error='The selected batch is not available.';else try{$p->beginTransaction();$p->prepare('DELETE ma FROM medical_adjustments ma JOIN attendance_records ar ON ar.id=ma.attendance_record_id JOIN attendance_sessions a ON a.id=ar.attendance_session_id JOIN batch_subjects bs ON bs.id=a.batch_subject_id WHERE bs.batch_id=?')->execute([$batchId]);$p->prepare('DELETE ar FROM attendance_records ar JOIN attendance_sessions a ON a.id=ar.attendance_session_id JOIN batch_subjects bs ON bs.id=a.batch_subject_id WHERE bs.batch_id=?')->execute([$batchId]);$p->prepare('DELETE a FROM attendance_sessions a JOIN batch_subjects bs ON bs.id=a.batch_subject_id WHERE bs.batch_id=?')->execute([$batchId]);$p->prepare('DELETE FROM batch_subjects WHERE batch_id=?')->execute([$batchId]);$p->prepare('DELETE FROM students WHERE batch_id=?')->execute([$batchId]);$p->prepare('DELETE FROM batches WHERE id=? AND department_id=?')->execute([$batchId,$departmentId]);$p->commit();flash('Batch and its students and attendance records were deleted.');redirect('/hod/batches/index.php');}catch(Throwable $e){if($p->inTransaction())$p->rollBack();$error='The batch could not be deleted.';}}}$q=$p->prepare('SELECT b.*,COUNT(s.id) students FROM batches b LEFT JOIN students s ON s.batch_id=b.id WHERE b.department_id=? GROUP BY b.id ORDER BY b.academic_year DESC');$q->execute([$departmentId]);$title='Batches';require __DIR__.'/../../includes/header.php';?><?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif?><p><a class="button" href="create.php">Create Batch</a></p><div class="panel table-wrap"><table><tr><th>Batch</th><th>Code</th><th>Year</th><th>Students</th><th>Status</th><th></th></tr><?php foreach($q as $b):?><tr><td><?=e($b['batch_name'])?></td><td><?=e($b['batch_code'])?></td><td><?=e($b['academic_year'])?></td><td><?=$b['students']?></td><td><?=e($b['status'])?></td><td class="actions"><a class="button secondary" href="edit.php?id=<?=$b['id']?>">Edit</a><a class="button" href="manage.php?batch_id=<?=$b['id']?>">Manage</a><form method="post" class="batch-delete-form" onsubmit="return confirm('Delete this batch, all students, and all attendance records?')"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="batch_id" value="<?=$b['id']?>"><input type="password" name="password" placeholder="HOD password" required><input type="text" name="confirmation" placeholder="Type DELETE BATCH" pattern="DELETE BATCH" required><button class="button danger" type="submit">Delete</button></form></td></tr><?php endforeach?></table></div><?php require __DIR__.'/../../includes/footer.php';?>
